<?php requirePermission('quotes');$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT q.*,c.name customer,c.document,c.phone,u.name seller FROM quotes q LEFT JOIN customers c ON c.id=q.customer_id JOIN users u ON u.id=q.user_id WHERE q.id=?');$st->execute([$id]);$q=$st->fetch();if(!$q){flash('error','Orçamento não encontrado.');redirect('index.php?page=quotes');}$it=$pdo->prepare('SELECT qi.*,p.name,p.sku FROM quote_items qi JOIN products p ON p.id=qi.product_id WHERE quote_id=?');$it->execute([$id]);$items=$it->fetchAll();$title='Orçamento #'.$id;require __DIR__.'/../../includes/header.php';?>
<div class="page-head"><div><h1>Orçamento #<?=$id?></h1><p>Validade: <?=date('d/m/Y',strtotime($q['valid_until']))?> · <?=e($q['seller'])?></p></div><button class="btn" onclick="window.print()">Imprimir</button></div><section class="panel receipt"><div class="receipt-brand"><h2><?=e(setting($pdo,'company_name','Dreamlast Comércio'))?></h2><small><?=e(setting($pdo,'company_document',''))?></small></div><p><strong>Cliente:</strong> <?=e($q['customer']?:'Consumidor final')?></p><table><thead><tr><th>Item</th><th>Qtd.</th><th>Unit.</th><th>Total</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['name'])?><small><?=e($i['sku'])?></small></td><td><?=$i['quantity']?></td><td><?=money($i['unit_price'])?></td><td><?=money($i['total'])?></td></tr><?php endforeach;?></tbody></table><div class="receipt-totals"><p>Subtotal <strong><?=money($q['subtotal'])?></strong></p><p>Desconto <strong><?=money($q['discount'])?></strong></p><p class="final">TOTAL <strong><?=money($q['total'])?></strong></p></div><p><?=nl2br(e($q['notes']))?></p><div class="receipt-footer">Orçamento sujeito à disponibilidade de estoque.</div></section><?php require __DIR__.'/../../includes/footer.php';?>
